        "**Biopsy when wheals last over 24 hours, burn or hurt rather than itch, or leave bruising or hyperpigmentation**. [EAACI 2022]",
        "Also biopsy when wheals come with **fever, arthralgia and a raised ESR** - this is urticarial vasculitis. [EAACI 2022]",
        "In urticarial vasculitis check **complement C3, C4 and C1q, antinuclear antibody and urinalysis for glomerulonephritis**. [EAACI 2022]",
        "**Urticarial vasculitis is treated by treating the underlying disease** - it is a sign, not a diagnosis in itself. [EAACI 2022]",
        "Score severity with the **Urticaria Activity Score over 7 days (UAS7)** - it turns a subjective complaint into a number. [EAACI 2022]",
        "UAS7 sums **daily wheal number 0 to 3 plus itch 0 to 3 over a week, to a maximum of 42** - use it to justify each escalation. [EAACI 2022]",
