        "**Avoid aggravants: NSAIDs including aspirin, opioids, alcohol, heat, tight clothing and stress** - all lower the mast cell threshold. [EAACI 2022]",
        "**Treat any identified infection or infestation** - a cleared focus can end urticaria that drugs only suppressed. [IADVL Textbook 5e]",
        "**In inducible urticaria, trigger avoidance plus a regular antihistamine is the whole of treatment**. [EAACI 2022]",
        "**In pregnancy use loratadine or cetirizine** - they have the best human safety record. [EAACI 2022]",
        "**In children use weight-appropriate second-generation antihistamines** - up-dose only cautiously and with specialist advice. [EAACI 2022]",
