        "**There is no absolute contraindication to adrenaline in anaphylaxis** - cardiac disease and pregnancy are not reasons to withhold it. [EAACI 2022]",
        "**Lay the patient flat with the legs raised** - sitting up only if breathless, left lateral in pregnancy. [EAACI 2022]",
        "**Do not let the patient stand or walk** - sudden upright posture in a hypotensive patient can cause empty ventricle arrest. [EAACI 2022]",
        "Give **high-flow oxygen and an intravenous crystalloid bolus of 20 mL per kilogram**, and secure the airway early. [EAACI 2022]",
