    "PASI",
    "calcipotriol",
    "methotrexate",
    "acitretin",
    "ciclosporin",
    "narrowband UVB",
    "biologics",
    "erythrodermic psoriasis",
    "generalised pustular psoriasis",
    "coal tar",
    "dithranol",
    "metabolic syndrome",
